document.addEventListener("DOMContentLoaded",()=>{const e=[{year:"1856",title:"Birth",description:"Born on July 23 in Ratnagiri, Maharashtra."},{year:"1884",title:"Deccan Education Society",description:"Co-founded the Deccan Education Society to teach nationalist ideas to the youth."},{year:"1890",title:"Indian National Congress",description:"Joined the Indian National Congress and soon became a strong critic of its moderate policies."},{year:"1893-1895",title:"Public Festivals",description:"Popularized the Ganesh Chaturthi (1893) and Shivaji Utsav (1895) to build national spirit beyond the educated elite."},{year:"1908",title:"Sedition & Imprisonment",description:"Sentenced to six years of imprisonment in Mandalay, Burma, for his writings in Kesari defending revolutionaries."},{year:"1916",title:"Home Rule League",description:"Founded the All India Home Rule League, demanding self-government for India."},{year:"1920",title:"Death",description:"Passed away on August 1. His death was mourned by millions, marking the end of an era."}],n=document.getElementById("timeline-container");n&&e.forEach(e=>{const t=document.createElement("div");t.className="timeline-item",t.tabIndex=0,t.innerHTML=`\n                <div class="timeline-year">${e.year}</div>\n                <div class="timeline-content">\n                    <h3>${e.title}</h3>\n                    <p>${e.description}</p>\n                </div>\n            `,n.appendChild(t)});const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1});document.querySelectorAll(".timeline-item").forEach(e=>t.observe(e));const i=[{title:"Nationalist Politics",desc:"Shifted the political discourse from petitions and prayers to assertive demands for rights."},{title:"Swadeshi Movement",desc:"A strong proponent of the Swadeshi (indigenous goods) movement and boycott of foreign goods following the 1905 Bengal partition."},{title:"Public Mobilization",desc:"Pioneered the use of mass mobilization through cultural festivals, transforming nationalism into a grassroots movement."},{title:"Home Rule Movement",desc:"Unified factions of the Congress and led the Home Rule Movement to demand dominion status for India."}],a=document.getElementById("contributions-container");a&&i.forEach(e=>{const n=document.createElement("div");n.className="contribution-card",n.tabIndex=0,n.innerHTML=`\n                <h3>${e.title}</h3>\n                <p>${e.desc}</p>\n            `,a.appendChild(n)});const o=[{name:"Kesari",lang:"Marathi",desc:"A daily newspaper used as a mouthpiece for the Indian national freedom movement, heavily critical of British policies."},{name:"The Mahratta",lang:"English",desc:"An English weekly aimed at a broader Indian and international audience, disseminating nationalist ideology."}],s=document.getElementById("newspapers-container");s&&o.forEach(e=>{const n=document.createElement("div");n.className="newspaper-card",n.tabIndex=0,n.innerHTML=`\n                <div class="newspaper-name">${e.name}</div>\n                <div class="newspaper-lang">${e.lang}</div>\n                <p>${e.desc}</p>\n            `,s.appendChild(n)});const d=document.getElementById("legacy-container");d&&(d.innerHTML="<div class=\"content-card\" tabindex=\"0\"><p>Tilak was famously called 'The Father of the Indian Unrest' by British author Valentine Chirol. Mahatma Gandhi referred to him as 'The Maker of Modern India'. His uncompromising stance on Swaraj laid the foundation for the mass movements that would eventually lead to India's independence.</p></div>");const r=[{text:"National Archives of India - Records on Bal Gangadhar Tilak",link:"#"},{text:"Bal Gangadhar Tilak: His Writings and Speeches - Academic Publication",link:"#"},{text:"Deccan Education Society Archives",link:"#"}],l=document.getElementById("references-container");l&&r.forEach(e=>{const n=document.createElement("li");n.innerHTML="#"!==e.link?`<a href="${e.link}" target="_blank" rel="noopener noreferrer">${e.text}</a>`:`<span>${e.text}</span>`,l.appendChild(n)})});